document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("lineVideo"),t=document.getElementById("videoTitle"),n=document.getElementById("toggleVideoBtn"),d=[{title:"生產線",src:"../video/生產線.mp4"},{title:"非金屬生產線",src:"../video/非金屬生產線.mp4"}];let i=0;n.addEventListener("click",()=>{i=(i+1)%d.length,e.src=d[i].src,t.innerText=`當前播放：${d[i].title}`,e.play();const l=d[(i+1)%d.length].title;n.title=`切換至 ${l}`})});